"""Small, traceable reference library; never misrepresents unavailable course PDFs."""
import copy

SOURCE = 'AI Video Course Review and Workflow · Production playbook'
ENTRIES = []


def add(id, category, name, explanation, use, risk, apply, variant='', provenance='studio_reference'):
    ENTRIES.append({'id': id, 'category': category, 'name': name, 'explanation': explanation,
                    'use_when': use, 'risk': risk, 'safer_alternative': 'Simplify the setup; test one change on the pilot.',
                    'apply': apply, 'visual': {'kind': category, 'variant': variant or id},
                    'source': SOURCE, 'section': 'Design individual shot cards' if category not in ['story', 'continuity', 'sound'] else 'Production playbook',
                    'provenance': provenance, 'source_note': 'Studio-authored practical example informed by the supplied playbook; not an extracted original-course catalogue entry.' if provenance == 'studio_reference' else 'Adapted from the supplied review/playbook. Original guide/page not independently verified here.'})


